-- create-table /TROTTO/OTTO_SHOPS
CREATE TABLE "/TROTTO/OTTO_SHOPS" (
  "/RT/TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "SHOP_ID" VARCHAR(12) COLLATE "C" NOT NULL,
  "COMPANY_ID" VARCHAR(10) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(80) COLLATE "C" NOT NULL,
  CONSTRAINT "/TROTTO/OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "/TROTTO/OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/TROTTO/OTTO_SHOPS#FK#CONNECTION" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TROTTO/OTTO_CONNECTIONS" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- alter-type /TRFIN/COMPANIES./TROTTO/OTTO_ID (CHAR(20) -> CHAR(32))
ALTER TABLE "/TRFIN/COMPANIES" ALTER COLUMN "/TROTTO/OTTO_ID" TYPE VARCHAR(32) COLLATE "C";

-- add-column /TRFIN/COMPANIES./TROTTO/ACTIVE (BOOL)
ALTER TABLE "/TRFIN/COMPANIES" ADD COLUMN "/TROTTO/ACTIVE" BOOLEAN NOT NULL DEFAULT FALSE;

-- add-column /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (CHAR(12))
ALTER TABLE "/TRFIN/COMPANIES" ADD COLUMN "/TROTTO/MAIN_SHOP" VARCHAR(12) COLLATE "C";

-- alter-type /TRFIN/COMPANIES_ARCHIVE./TROTTO/OTTO_ID (CHAR(20) -> CHAR(32)) via /TRFIN/COMPANIES
ALTER TABLE "/TRFIN/COMPANIES_ARCHIVE" ALTER COLUMN "/TROTTO/OTTO_ID" TYPE VARCHAR(32) COLLATE "C";

-- add-column /TRFIN/COMPANIES_ARCHIVE./TROTTO/ACTIVE (BOOL) via /TRFIN/COMPANIES
ALTER TABLE "/TRFIN/COMPANIES_ARCHIVE" ADD COLUMN "/TROTTO/ACTIVE" BOOLEAN NOT NULL DEFAULT FALSE;

-- add-column /TRFIN/COMPANIES_ARCHIVE./TROTTO/MAIN_SHOP (CHAR(12)) via /TRFIN/COMPANIES
ALTER TABLE "/TRFIN/COMPANIES_ARCHIVE" ADD COLUMN "/TROTTO/MAIN_SHOP" VARCHAR(12) COLLATE "C";

-- add-foreign-key /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (references /TROTTO/OTTO_SHOPS)
ALTER TABLE "/TRFIN/COMPANIES" ADD CONSTRAINT "/TRFIN/COMPANIES#FK#/TROTTO/MAIN_SHOP" FOREIGN KEY ("/RT/TENANT", "/TROTTO/MAIN_SHOP") REFERENCES "/TROTTO/OTTO_SHOPS" ("/RT/TENANT", "SHOP_ID") DEFERRABLE INITIALLY IMMEDIATE;

